import React, { useState } from 'react';
import { OrbMain } from '../components/Orb';
import { analyzeThought } from '../hooks/useGroq';
import { useThoughts } from '../hooks/useStorage';

const CIRCLE_SM = {
  width: 54, height: 54, borderRadius: '50%',
  background: 'rgba(255,255,255,0.6)',
  border: '1px solid rgba(255,255,255,0.9)',
  display: 'flex', alignItems: 'center', justifyContent: 'center',
  cursor: 'pointer', transition: 'all 0.25s cubic-bezier(0.34,1.4,0.64,1)',
  WebkitTapHighlightColor: 'transparent',
};
const CIRCLE_LG = {
  width: 70, height: 70, borderRadius: '50%',
  background: '#1A2A2A', color: '#EEEAE3',
  display: 'flex', alignItems: 'center', justifyContent: 'center',
  cursor: 'pointer',
  boxShadow: '0 8px 28px rgba(26,42,42,0.22)',
  transition: 'all 0.25s cubic-bezier(0.34,1.4,0.64,1)',
  border: 'none',
  WebkitTapHighlightColor: 'transparent',
};
const CIRC_LBL = {
  fontSize: 9, fontWeight: 700, letterSpacing: '0.07em',
  textTransform: 'uppercase', color: 'rgba(26,42,42,0.32)',
  textAlign: 'center', marginTop: 5,
};

export default function Home({ setPage, streak }) {
  const [inputOpen, setInputOpen] = useState(false);
  const [text,      setText]      = useState('');
  const [loading,   setLoading]   = useState(false);
  const [error,     setError]     = useState('');
  const [result,    setResult]    = useState(null);
  const { addThought } = useThoughts();

  const submit = async () => {
    if (!text.trim() || loading) return;
    setLoading(true); setError('');
    try {
      const ai = await analyzeThought(text);
      const entry = { id: Date.now(), user_text: text, ...ai, date: new Date().toISOString() };
      addThought(entry);
      setResult(entry);
      setInputOpen(false);
    } catch { setError('Something went wrong. Try again.'); }
    setLoading(false);
  };

  if (result) return (
    <Analysis
      result={result}
      text={text}
      onBack={() => { setResult(null); setText(''); }}
      setPage={setPage}
    />
  );

  return (
    <div style={{ position: 'relative', minHeight: '100vh', background: '#EEEAE3', overflow: 'hidden' }}>
      <OrbMain />

      {/* Loading */}
      {loading && (
        <div style={{ position: 'absolute', inset: 0, zIndex: 250, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 20, background: 'rgba(238,234,227,0.72)', backdropFilter: 'blur(12px)' }}>
          <div style={{ width: 68, height: 68, borderRadius: '50%', background: 'radial-gradient(circle at 38% 35%, #7EC8C8, #2D6B6B)', animation: 'loadPulse 1.2s ease-in-out infinite' }} />
          <p style={{ fontSize: 13, fontWeight: 500, color: 'rgba(26,42,42,0.4)' }}>Analysing…</p>
        </div>
      )}

      <div style={{ display: 'flex', flexDirection: 'column', justifyContent: 'space-between', minHeight: '100vh', padding: '48px 24px 44px', position: 'relative', zIndex: 10 }}>

        {/* Logo + streak */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <span style={{ fontSize: 12, fontWeight: 600, letterSpacing: '-0.02em', color: 'rgba(26,42,42,0.35)' }}>spiral</span>
          {streak > 0 && (
            <div style={{ padding: '6px 12px', borderRadius: 999, background: 'rgba(26,42,42,0.07)', fontSize: 11, fontWeight: 600, color: '#2D6B6B' }}>
              🔥 {streak} {streak === 1 ? 'day' : 'days'}
            </div>
          )}
        </div>

        {/* Headline */}
        <div style={{ animation: 'fadeIn 0.7s 0.15s both' }}>
          <h1 style={{ fontSize: 40, fontWeight: 700, letterSpacing: '-0.055em', lineHeight: 1.01, color: '#1A2A2A' }}>
            Break<br />the <span style={{ color: '#2D6B6B' }}>spiral.</span>
          </h1>
          <p style={{ fontSize: 13, color: 'rgba(26,42,42,0.38)', marginTop: 10, lineHeight: 1.6, maxWidth: 200 }}>
            Write down the thought. AI identifies the pattern.
          </p>
        </div>

        {/* Circle actions */}
        <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'flex-end', gap: 14, animation: 'fadeIn 0.7s 0.3s both' }}>

          {/* Check-in */}
          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 6 }}>
            <button
              onClick={() => setPage('checkin')}
              style={{ ...CIRCLE_SM, color: 'rgba(26,42,42,0.4)' }}
              aria-label="Check-in"
            >
              <svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                <circle cx="12" cy="12" r="9"/><path d="M8 12l3 3 5-5"/>
              </svg>
            </button>
            <span style={CIRC_LBL}>Check-in</span>
          </div>

          {/* FAB — new thought */}
          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 6 }}>
            <button
              onClick={() => setInputOpen(true)}
              style={CIRCLE_LG}
              aria-label="New thought"
              onMouseEnter={e => { e.currentTarget.style.transform = 'scale(1.07)'; e.currentTarget.style.boxShadow = '0 12px 36px rgba(26,42,42,0.3)'; }}
              onMouseLeave={e => { e.currentTarget.style.transform = 'scale(1)'; e.currentTarget.style.boxShadow = '0 8px 28px rgba(26,42,42,0.22)'; }}
            >
              <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#EEEAE3" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
                <path d="M12 5v14M5 12h14"/>
              </svg>
            </button>
            <span style={{ ...CIRC_LBL, color: 'rgba(26,42,42,0.5)', fontWeight: 700 }}>New thought</span>
          </div>

          {/* Breathe */}
          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 6 }}>
            <button
              onClick={() => setPage('breathing')}
              style={{ ...CIRCLE_SM, color: 'rgba(26,42,42,0.4)' }}
              aria-label="Breathe"
            >
              <svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                <path d="M12 4c0 0-4 3-4 7s4 5 4 9"/><path d="M12 4c0 0 4 3 4 7s-4 5-4 9"/>
              </svg>
            </button>
            <span style={CIRC_LBL}>Breathe</span>
          </div>

        </div>
      </div>

      {/* Input sheet */}
      {inputOpen && (
        <div style={{ position: 'absolute', inset: 0, zIndex: 200, display: 'flex', flexDirection: 'column', justifyContent: 'flex-end', background: 'rgba(20,32,32,0.22)', backdropFilter: 'blur(4px)', animation: 'fadeIn 0.25s ease' }}>
          <div onClick={() => setInputOpen(false)} style={{ flex: 1 }} />
          <div style={{ margin: '0 10px 12px', borderRadius: 30, padding: '26px 22px 22px', background: 'rgba(238,234,227,0.97)', backdropFilter: 'blur(40px)', border: '1px solid rgba(255,255,255,0.85)', boxShadow: '0 -6px 50px rgba(26,42,42,0.1)', animation: 'slideUp 0.38s cubic-bezier(0.16,1,0.3,1)', position: 'relative' }}>
            <button onClick={() => setInputOpen(false)} style={{ position: 'absolute', top: 22, right: 22, width: 28, height: 28, borderRadius: '50%', background: 'rgba(26,42,42,0.07)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 13, color: 'rgba(26,42,42,0.4)', cursor: 'pointer', border: 'none' }}>✕</button>
            <div style={{ fontSize: 10, fontWeight: 700, color: 'rgba(26,42,42,0.28)', letterSpacing: '0.12em', textTransform: 'uppercase', marginBottom: 13 }}>What's on your mind?</div>
            <textarea
              autoFocus
              value={text}
              onChange={e => setText(e.target.value)}
              maxLength={1000}
              placeholder="Write freely…"
              style={{ width: '100%', minHeight: 120, background: 'transparent', border: 'none', outline: 'none', fontSize: 17, lineHeight: 1.65, color: '#1A2A2A', resize: 'none', fontFamily: "'Inter', sans-serif" }}
            />
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', paddingTop: 14, borderTop: '1px solid rgba(26,42,42,0.08)', marginTop: 4 }}>
              <span style={{ fontSize: 11, color: 'rgba(26,42,42,0.25)' }}>{text.length} / 1000</span>
              <button
                onClick={submit}
                disabled={!text.trim() || loading}
                style={{ padding: '11px 22px', borderRadius: 999, background: text.trim() && !loading ? '#1A2A2A' : 'rgba(26,42,42,0.1)', color: text.trim() && !loading ? '#EEEAE3' : 'rgba(26,42,42,0.25)', fontSize: 13, fontWeight: 600, border: 'none', cursor: text.trim() ? 'pointer' : 'default', transition: 'all 0.2s', fontFamily: "'Inter', sans-serif" }}
              >
                Analyse →
              </button>
            </div>
            {error && <p style={{ fontSize: 12, color: 'rgba(200,80,80,0.8)', marginTop: 10 }}>{error}</p>}
          </div>
        </div>
      )}
    </div>
  );
}

function Analysis({ result, text, onBack, setPage }) {
  const sections = [
    { label: "What's happening", body: result.description },
    { label: 'Reframe',          body: result.reframe },
    { label: 'Exercise',         body: result.exercise_text },
  ];
  return (
    <div style={{ background: '#EEEAE3', minHeight: '100vh', overflowY: 'auto', position: 'relative' }}>
      <div style={{ position: 'fixed', left: '50%', transform: 'translateX(-50%)', width: 340, height: 340, top: 60, borderRadius: '50%', pointerEvents: 'none', background: 'radial-gradient(circle at 40% 40%, rgba(200,120,100,0.22) 0%, rgba(100,50,50,0.08) 50%, transparent 75%)', filter: 'blur(30px)', zIndex: 0 }} />
      <div style={{ padding: '56px 24px 110px', position: 'relative', zIndex: 1 }}>
        <button onClick={onBack} style={{ fontSize: 13, fontWeight: 500, color: '#2D6B6B', marginBottom: 32, display: 'block', background: 'none', border: 'none', cursor: 'pointer', padding: 0, fontFamily: "'Inter', sans-serif" }}>← Back</button>
        <div style={{ display: 'inline-flex', alignItems: 'center', gap: 7, padding: '7px 14px', borderRadius: 999, background: 'rgba(45,107,107,0.1)', border: '1px solid rgba(45,107,107,0.15)', marginBottom: 14 }}>
          <div style={{ width: 6, height: 6, borderRadius: '50%', background: '#2D6B6B' }} />
          <span style={{ fontSize: 11, fontWeight: 700, color: '#2D6B6B', letterSpacing: '0.05em', textTransform: 'uppercase' }}>{result.trap_label}</span>
        </div>
        <h2 style={{ fontSize: 32, fontWeight: 700, letterSpacing: '-0.05em', lineHeight: 1.04, color: '#1A2A2A', marginBottom: 24 }}>{result.trap_label}.</h2>
        <div style={{ padding: '16px 18px', borderRadius: '0 16px 16px 0', borderLeft: '3px solid #2D6B6B', background: 'rgba(45,107,107,0.05)', marginBottom: 20 }}>
          <p style={{ fontSize: 14, lineHeight: 1.7, color: 'rgba(26,42,42,0.5)', fontStyle: 'italic' }}>"{text.slice(0, 120)}{text.length > 120 ? '…' : ''}"</p>
        </div>
        {sections.map(({ label, body }) => (
          <div key={label} style={{ padding: 18, borderRadius: 20, marginBottom: 10, background: 'rgba(255,255,255,0.55)', border: '1px solid rgba(255,255,255,0.9)' }}>
            <div style={{ fontSize: 10, fontWeight: 700, color: '#2D6B6B', letterSpacing: '0.1em', textTransform: 'uppercase', marginBottom: 7 }}>{label}</div>
            <p style={{ fontSize: 15, lineHeight: 1.7, color: '#1A2A2A', fontWeight: 400 }}>{body}</p>
          </div>
        ))}
        <button onClick={() => setPage('breathing')} style={{ width: '100%', padding: 16, borderRadius: 18, marginTop: 6, border: '1.5px solid rgba(26,42,42,0.12)', color: '#1A2A2A', fontSize: 14, fontWeight: 500, background: 'transparent', cursor: 'pointer', fontFamily: "'Inter', sans-serif" }}>
          Breathing exercise →
        </button>
      </div>
    </div>
  );
}
